#include <math.h>

#define Y_PIN A5
#define X_PIN A5
#define SW_PIN 2

boolean internal_variable_isJoystickButtonPressed = false;
boolean internal_variable_isJoyStickEngaged = false;
int internal_variable_degrees = 0;




